INSERT INTO `oc_information_to_store` (`information_id`,`store_id`) VALUES (15,0),(16,0);
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (15,1,'Як встановити модуль CodeCart PRO на OpenCart та ocStore','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;Як встановити модуль CodeCart PRO на OpenCart та ocStore&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;Усі модулі CodeCart PRO встановлюються стандартним установником OpenCart — архівом .ocmod.zip, без FTP і правок ядра. Це займе 5–10 хвилин.&lt;/p&gt;&lt;ol class=&quot;st&quot;&gt;&lt;li&gt;&lt;b&gt;Зробіть резервну копію&lt;/b&gt;Збережіть файли сайту та базу даних. Для модулів, що змінюють базу чи зображення, це обов’язково. Краще спочатку перевірити модуль на тестовій копії магазину.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Завантажте архів&lt;/b&gt;Адмінка → Додатки → Встановлення розширень → «Завантажити» і оберіть файл .ocmod.zip. Дочекайтеся повідомлення про успішне встановлення.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Оновіть модифікатори&lt;/b&gt;Адмінка → Додатки → Модифікації → кнопка «Оновити». Потім очистіть кеш Twig/теми та кеш сторінок чи CDN, якщо він увімкнений.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Встановіть розширення&lt;/b&gt;Адмінка → Додатки → Додатки, оберіть тип (найчастіше «Модулі»), знайдіть модуль і натисніть зелену кнопку «Встановити», потім «Редагувати».&lt;/li&gt;&lt;li&gt;&lt;b&gt;Активуйте ліцензію&lt;/b&gt;Введіть ключ із замовлення в налаштуваннях модуля. Ліцензії CodeCart PRO постійні: вони прив’язані до домену й не потребують щорічного продовження.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Увімкніть і перевірте&lt;/b&gt;Більшість модулів після встановлення вимкнені. Налаштуйте параметри, увімкніть статус, збережіть і перевірте роботу на вітрині чи в адмінці.&lt;/li&gt;&lt;/ol&gt;&lt;h3&gt;Оновлення та видалення&lt;/h3&gt;&lt;div class=&quot;box&quot;&gt;Оновлення: зробіть резервну копію, завантажте новий архів поверх встановленого, оновіть модифікатори й відкрийте модуль — натисніть «Зберегти» один раз. Видалення: вимкніть модуль, натисніть «Видалити» у списку додатків, потім видаліть архів у «Встановленні розширень» і оновіть модифікатори.&lt;/div&gt;&lt;div class=&quot;box warn&quot;&gt;Сумісність: OpenCart 3.0.x та ocStore 3.0.x (зокрема 3.0.4.1). Вимоги до версії PHP вказані на сторінці кожного модуля. Перед купівлею можна відкрити демо-адмінку: demo.codecartpro.com/admin (логін і пароль: Demo).&lt;/div&gt;&lt;p&gt;Потрібна допомога? Напишіть на support@codecartpro.com — підкажемо щодо встановлення й налаштування.&lt;/p&gt;&lt;/div&gt;','Як встановити модуль OpenCart/ocStore (.ocmod.zip) — покрокова інструкція','Покрокове встановлення модулів CodeCart PRO на OpenCart 3.0.x та ocStore 3.0.x: резервна копія, установник, модифікатори, ліцензія, оновлення та видалення.','','Як встановити модуль CodeCart PRO на OpenCart та ocStore');
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (15,2,'How to install a CodeCart PRO module on OpenCart and ocStore','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;How to install a CodeCart PRO module on OpenCart and ocStore&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;Every CodeCart PRO module installs through the standard OpenCart installer as an .ocmod.zip archive — no FTP and no core edits. It takes 5–10 minutes.&lt;/p&gt;&lt;ol class=&quot;st&quot;&gt;&lt;li&gt;&lt;b&gt;Make a backup&lt;/b&gt;Save your site files and database. It is mandatory for modules that change the database or images. Ideally test the module on a staging copy first.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Upload the archive&lt;/b&gt;Admin → Extensions → Installer → “Upload” and choose the .ocmod.zip file. Wait for the success message.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Refresh modifications&lt;/b&gt;Admin → Extensions → Modifications → “Refresh”. Then clear the Twig/theme cache and the page or CDN cache if you use one.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Install the extension&lt;/b&gt;Admin → Extensions → Extensions, pick the type (usually “Modules”), find the module, click the green “Install” button, then “Edit”.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Activate the license&lt;/b&gt;Enter the key from your order in the module settings. CodeCart PRO licenses are lifetime: bound to a domain, with no yearly renewal.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Enable and verify&lt;/b&gt;Most modules are OFF after install. Set the options, enable the status, save and check the result on the storefront or in the admin.&lt;/li&gt;&lt;/ol&gt;&lt;h3&gt;Updating and removing&lt;/h3&gt;&lt;div class=&quot;box&quot;&gt;Update: back up, upload the new archive over the installed one, refresh modifications and open the module — press “Save” once. Remove: disable the module, click “Uninstall” in the extension list, then delete the archive in the Installer and refresh modifications.&lt;/div&gt;&lt;div class=&quot;box warn&quot;&gt;Compatibility: OpenCart 3.0.x and ocStore 3.0.x (including 3.0.4.1). PHP requirements are shown on each module page. Before buying you can open the demo admin: demo.codecartpro.com/admin (login and password: Demo).&lt;/div&gt;&lt;p&gt;Need help? Write to support@codecartpro.com — we will guide you through installation and setup.&lt;/p&gt;&lt;/div&gt;','How to install an OpenCart/ocStore module (.ocmod.zip) — step by step','Step-by-step installation of CodeCart PRO modules on OpenCart 3.0.x and ocStore 3.0.x: backup, installer, modifications, license, update and removal.','','How to install a CodeCart PRO module on OpenCart and ocStore');
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (15,3,'Как установить модуль CodeCart PRO на OpenCart и ocStore','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;Как установить модуль CodeCart PRO на OpenCart и ocStore&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;Все модули CodeCart PRO устанавливаются стандартным установщиком OpenCart — архивом .ocmod.zip, без FTP и правок ядра. Займёт 5–10 минут.&lt;/p&gt;&lt;ol class=&quot;st&quot;&gt;&lt;li&gt;&lt;b&gt;Сделайте резервную копию&lt;/b&gt;Сохраните файлы сайта и базу данных. Для модулей, которые меняют базу или изображения, это обязательно. Лучше сначала проверить модуль на тестовой копии магазина.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Загрузите архив&lt;/b&gt;Админка → Дополнения → Установка расширений → «Загрузить» и выберите файл .ocmod.zip. Дождитесь сообщения об успешной установке.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Обновите модификаторы&lt;/b&gt;Админка → Дополнения → Модификации → кнопка «Обновить». Затем очистите кеш Twig/темы и кеш страниц или CDN, если он у вас включён.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Установите расширение&lt;/b&gt;Админка → Дополнения → Дополнения, выберите тип (чаще всего «Модули»), найдите модуль и нажмите зелёную кнопку «Установить», затем «Изменить».&lt;/li&gt;&lt;li&gt;&lt;b&gt;Активируйте лицензию&lt;/b&gt;Введите ключ из заказа в настройках модуля. Лицензии CodeCart PRO постоянные: они привязаны к домену и не требуют ежегодного продления.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Включите и проверьте&lt;/b&gt;Большинство модулей после установки выключены. Настройте параметры, включите статус, сохраните и проверьте работу на витрине или в админке.&lt;/li&gt;&lt;/ol&gt;&lt;h3&gt;Обновление и удаление&lt;/h3&gt;&lt;div class=&quot;box&quot;&gt;Обновление: сделайте резервную копию, загрузите новый архив поверх установленного, обновите модификаторы и откройте модуль — нажмите «Сохранить» один раз. Удаление: выключите модуль, нажмите «Удалить» в списке дополнений, затем удалите архив в «Установке расширений» и обновите модификаторы.&lt;/div&gt;&lt;div class=&quot;box warn&quot;&gt;Совместимость: OpenCart 3.0.x и ocStore 3.0.x (включая 3.0.4.1). Требования к версии PHP указаны на странице каждого модуля. Перед покупкой можно открыть демо-админку: demo.codecartpro.com/admin (логин и пароль: Demo).&lt;/div&gt;&lt;p&gt;Нужна помощь? Напишите на support@codecartpro.com — подскажем по установке и настройке.&lt;/p&gt;&lt;/div&gt;','Как установить модуль OpenCart/ocStore (.ocmod.zip) — пошаговая инструкция','Пошаговая установка модулей CodeCart PRO на OpenCart 3.0.x и ocStore 3.0.x: резервная копия, установщик, модификаторы, лицензия, обновление и удаление.','','Как установить модуль CodeCart PRO на OpenCart и ocStore');
INSERT INTO `oc_seo_url` (`store_id`,`language_id`,`query`,`keyword`) VALUES (0,1,'information_id=15','yak-vstanovyty-modul'),(0,2,'information_id=15','how-to-install-modules'),(0,3,'information_id=15','kak-ustanovit-modul');
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (16,1,'Поширені запитання про модулі та систему CodeCart PRO','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;Поширені запитання про модулі та систему CodeCart PRO&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;Коротко про головне: що безкоштовно, що платно та як усе перевірити до купівлі.&lt;/p&gt;&lt;details&gt;&lt;summary&gt;Система CodeCart PRO справді безкоштовна?&lt;/summary&gt;&lt;p&gt;Так. CodeCart PRO 3.0.6.0 — вільна система під GNU GPL v3, її можна завантажити без реєстрації на сторінці «Завантажити». Платними тут є окремі модулі.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Як перевірити модуль до купівлі?&lt;/summary&gt;&lt;p&gt;Відкрийте демо-адмінку demo.codecartpro.com/admin (логін і пароль: Demo) та перегляньте налаштування модулів. Склад демо може змінюватися — перевіряйте потрібну функцію перед купівлею.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Які версії OpenCart і PHP підтримуються?&lt;/summary&gt;&lt;p&gt;Модулі розраховані на OpenCart 3.0.x та ocStore 3.0.x (зокрема 3.0.4.1). Діапазон PHP залежить від модуля — зазвичай 7.4–8.5, він вказаний в описі.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Як працює ліцензія?&lt;/summary&gt;&lt;p&gt;Ліцензія постійна й прив’язана до домену. Ключ вводиться в налаштуваннях модуля; щорічного продовження для роботи модуля не потрібно.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Як встановити модуль?&lt;/summary&gt;&lt;p&gt;Стандартним установником OpenCart, архівом .ocmod.zip. Докладно: сторінка «Як встановити модуль».&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Модулі змінюють файли ядра?&lt;/summary&gt;&lt;p&gt;Ні. Модулі працюють через OCMOD, події та власні файли; зміни оборотні — їх можна вимкнути й видалити.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Що буде після оновлення модуля?&lt;/summary&gt;&lt;p&gt;Завантажте новий архів поверх старого, оновіть модифікатори й один раз збережіть налаштування. Перед оновленням робіть резервну копію.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Куди звернутися по допомогу?&lt;/summary&gt;&lt;p&gt;Напишіть на support@codecartpro.com або в Telegram-спільноту проєкту. Умови ліцензії, гарантії та повернення — на сторінці «Ліцензія, гарантія та повернення».&lt;/p&gt;&lt;/details&gt;&lt;/div&gt;&lt;script type=&quot;application/ld+json&quot;&gt;{&quot;@context&quot;: &quot;https://schema.org&quot;, &quot;@type&quot;: &quot;FAQPage&quot;, &quot;mainEntity&quot;: [{&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Система CodeCart PRO справді безкоштовна?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Так. CodeCart PRO 3.0.6.0 — вільна система під GNU GPL v3, її можна завантажити без реєстрації на сторінці «Завантажити». Платними тут є окремі модулі.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Як перевірити модуль до купівлі?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Відкрийте демо-адмінку demo.codecartpro.com/admin (логін і пароль: Demo) та перегляньте налаштування модулів. Склад демо може змінюватися — перевіряйте потрібну функцію перед купівлею.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Які версії OpenCart і PHP підтримуються?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Модулі розраховані на OpenCart 3.0.x та ocStore 3.0.x (зокрема 3.0.4.1). Діапазон PHP залежить від модуля — зазвичай 7.4–8.5, він вказаний в описі.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Як працює ліцензія?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Ліцензія постійна й прив’язана до домену. Ключ вводиться в налаштуваннях модуля; щорічного продовження для роботи модуля не потрібно.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Як встановити модуль?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Стандартним установником OpenCart, архівом .ocmod.zip. Докладно: сторінка «Як встановити модуль».&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Модулі змінюють файли ядра?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Ні. Модулі працюють через OCMOD, події та власні файли; зміни оборотні — їх можна вимкнути й видалити.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Що буде після оновлення модуля?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Завантажте новий архів поверх старого, оновіть модифікатори й один раз збережіть налаштування. Перед оновленням робіть резервну копію.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Куди звернутися по допомогу?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Напишіть на support@codecartpro.com або в Telegram-спільноту проєкту. Умови ліцензії, гарантії та повернення — на сторінці «Ліцензія, гарантія та повернення».&quot;}}]}&lt;/script&gt;','FAQ: модулі CodeCart PRO, ліцензії, демо, встановлення','Відповіді на поширені запитання: чи безкоштовна система CodeCart PRO 3.0.6.0, як перевірити модуль, які версії OpenCart підтримуються, як працює ліцензія та оновлення.','','Поширені запитання про модулі та систему CodeCart PRO');
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (16,2,'CodeCart PRO modules and system — frequently asked questions','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;CodeCart PRO modules and system — frequently asked questions&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;The essentials: what is free, what is paid and how to check everything before you buy.&lt;/p&gt;&lt;details&gt;&lt;summary&gt;Is the CodeCart PRO system really free?&lt;/summary&gt;&lt;p&gt;Yes. CodeCart PRO 3.0.6.0 is free software under GNU GPL v3 and can be downloaded without registration on the Download page. Only the separate modules are paid.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;How can I test a module before buying?&lt;/summary&gt;&lt;p&gt;Open the demo admin at demo.codecartpro.com/admin (login and password: Demo) and review the module settings. Demo contents may change — check the feature you need before purchasing.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Which OpenCart and PHP versions are supported?&lt;/summary&gt;&lt;p&gt;Modules target OpenCart 3.0.x and ocStore 3.0.x (including 3.0.4.1). The PHP range depends on the module — usually 7.4–8.5, shown in its description.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;How does licensing work?&lt;/summary&gt;&lt;p&gt;The license is lifetime and bound to a domain. The key is entered in the module settings; no yearly renewal is needed for the module to work.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;How do I install a module?&lt;/summary&gt;&lt;p&gt;With the standard OpenCart installer using the .ocmod.zip archive. Details: the “How to install a module” page.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Do modules change core files?&lt;/summary&gt;&lt;p&gt;No. Modules work through OCMOD, events and their own files; changes are reversible — you can disable and remove them.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;What happens when I update a module?&lt;/summary&gt;&lt;p&gt;Upload the new archive over the old one, refresh modifications and save the settings once. Back up before updating.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Where do I get help?&lt;/summary&gt;&lt;p&gt;Write to support@codecartpro.com or join the project’s Telegram community. License, warranty and refund terms are on the “License, Warranty and Refunds” page.&lt;/p&gt;&lt;/details&gt;&lt;/div&gt;&lt;script type=&quot;application/ld+json&quot;&gt;{&quot;@context&quot;: &quot;https://schema.org&quot;, &quot;@type&quot;: &quot;FAQPage&quot;, &quot;mainEntity&quot;: [{&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Is the CodeCart PRO system really free?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Yes. CodeCart PRO 3.0.6.0 is free software under GNU GPL v3 and can be downloaded without registration on the Download page. Only the separate modules are paid.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;How can I test a module before buying?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Open the demo admin at demo.codecartpro.com/admin (login and password: Demo) and review the module settings. Demo contents may change — check the feature you need before purchasing.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Which OpenCart and PHP versions are supported?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Modules target OpenCart 3.0.x and ocStore 3.0.x (including 3.0.4.1). The PHP range depends on the module — usually 7.4–8.5, shown in its description.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;How does licensing work?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;The license is lifetime and bound to a domain. The key is entered in the module settings; no yearly renewal is needed for the module to work.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;How do I install a module?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;With the standard OpenCart installer using the .ocmod.zip archive. Details: the “How to install a module” page.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Do modules change core files?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;No. Modules work through OCMOD, events and their own files; changes are reversible — you can disable and remove them.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;What happens when I update a module?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Upload the new archive over the old one, refresh modifications and save the settings once. Back up before updating.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Where do I get help?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Write to support@codecartpro.com or join the project’s Telegram community. License, warranty and refund terms are on the “License, Warranty and Refunds” page.&quot;}}]}&lt;/script&gt;','FAQ: CodeCart PRO modules, licenses, demo, installation','Answers to common questions: is the CodeCart PRO 3.0.6.0 system free, how to test a module, which OpenCart versions are supported, how licensing and updates work.','','CodeCart PRO modules and system — frequently asked questions');
INSERT INTO `oc_information_description` (`information_id`,`language_id`,`title`,`description`,`meta_title`,`meta_description`,`meta_keyword`,`meta_h1`) VALUES (16,3,'Частые вопросы о модулях и системе CodeCart PRO','&lt;style&gt;.ccg{color:var(--cc-text,#0b1b3a);line-height:1.7;font-size:16px}.ccg h2{font-size:clamp(24px,3vw,32px);font-weight:850;margin:0 0 12px}.ccg h3{font-size:19px;font-weight:850;margin:26px 0 10px}.ccg .lead{font-size:18px;font-weight:600;margin:0 0 20px}.ccg ol.st{list-style:none;counter-reset:s;margin:0 0 20px;padding:0;display:grid;gap:12px}.ccg ol.st li{counter-increment:s;position:relative;padding:16px 18px 16px 64px;border:1px solid var(--cc-line,#d9e5f7);border-radius:16px;background:var(--cc-card,#fff);box-shadow:0 8px 22px rgba(10,60,160,.06)}.ccg ol.st li:before{content:counter(s);position:absolute;left:16px;top:14px;width:36px;height:36px;border-radius:50%;background:linear-gradient(165deg,#ffe07a,#ffc21a 60%,#f0a000);color:#0b1b3a;font-weight:900;display:flex;align-items:center;justify-content:center}.ccg ol.st b{display:block;margin-bottom:2px}.ccg .box{padding:16px 20px;border-radius:14px;background:#eef5ff;border:1px solid #cfe0ff;margin:0 0 18px}.ccg .warn{background:#fff8dc;border-color:#f0dd85;color:#5c4a00}.ccg details{border:1px solid var(--cc-line,#d9e5f7);border-radius:14px;padding:14px 18px;margin:0 0 10px;background:var(--cc-card,#fff)}.ccg summary{cursor:pointer;font-weight:800}.ccg details p{margin:10px 0 0}html.ccp-dark-theme .ccg .box{background:#12274d;border-color:#27406e}html.ccp-dark-theme .ccg .warn{background:#3a3210;border-color:#6a5a14;color:#ffeaa0}&lt;/style&gt;&lt;div class=&quot;ccg&quot;&gt;&lt;h2&gt;Частые вопросы о модулях и системе CodeCart PRO&lt;/h2&gt;&lt;p class=&quot;lead&quot;&gt;Коротко о главном: что бесплатно, что платно и как всё проверить до покупки.&lt;/p&gt;&lt;details&gt;&lt;summary&gt;Система CodeCart PRO действительно бесплатная?&lt;/summary&gt;&lt;p&gt;Да. CodeCart PRO 3.0.6.0 — свободная система под GNU GPL v3, её можно скачать без регистрации на странице «Скачать». Платные здесь — отдельные модули.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Как проверить модуль до покупки?&lt;/summary&gt;&lt;p&gt;Откройте демо-админку demo.codecartpro.com/admin (логин и пароль: Demo) и посмотрите настройки модулей. Состав демо может меняться — проверяйте нужную функцию перед покупкой.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Какие версии OpenCart и PHP поддерживаются?&lt;/summary&gt;&lt;p&gt;Модули рассчитаны на OpenCart 3.0.x и ocStore 3.0.x (включая 3.0.4.1). Диапазон PHP зависит от модуля — обычно 7.4–8.5, он указан в описании.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Как работает лицензия?&lt;/summary&gt;&lt;p&gt;Лицензия постоянная и привязана к домену. Ключ вводится в настройках модуля; ежегодного продления для работы модуля не требуется.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Как установить модуль?&lt;/summary&gt;&lt;p&gt;Стандартным установщиком OpenCart, архивом .ocmod.zip. Подробно: страница «Как установить модуль».&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Модули меняют файлы ядра?&lt;/summary&gt;&lt;p&gt;Нет. Модули работают через OCMOD, события и собственные файлы; изменения обратимы — их можно отключить и удалить.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Что будет после обновления модуля?&lt;/summary&gt;&lt;p&gt;Загрузите новый архив поверх старого, обновите модификаторы и один раз сохраните настройки. Перед обновлением делайте резервную копию.&lt;/p&gt;&lt;/details&gt;&lt;details&gt;&lt;summary&gt;Куда обратиться за помощью?&lt;/summary&gt;&lt;p&gt;Напишите на support@codecartpro.com или в Telegram-сообщество проекта. Условия лицензии, гарантии и возврата — на странице «Лицензия, гарантия и возврат».&lt;/p&gt;&lt;/details&gt;&lt;/div&gt;&lt;script type=&quot;application/ld+json&quot;&gt;{&quot;@context&quot;: &quot;https://schema.org&quot;, &quot;@type&quot;: &quot;FAQPage&quot;, &quot;mainEntity&quot;: [{&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Система CodeCart PRO действительно бесплатная?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Да. CodeCart PRO 3.0.6.0 — свободная система под GNU GPL v3, её можно скачать без регистрации на странице «Скачать». Платные здесь — отдельные модули.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Как проверить модуль до покупки?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Откройте демо-админку demo.codecartpro.com/admin (логин и пароль: Demo) и посмотрите настройки модулей. Состав демо может меняться — проверяйте нужную функцию перед покупкой.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Какие версии OpenCart и PHP поддерживаются?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Модули рассчитаны на OpenCart 3.0.x и ocStore 3.0.x (включая 3.0.4.1). Диапазон PHP зависит от модуля — обычно 7.4–8.5, он указан в описании.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Как работает лицензия?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Лицензия постоянная и привязана к домену. Ключ вводится в настройках модуля; ежегодного продления для работы модуля не требуется.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Как установить модуль?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Стандартным установщиком OpenCart, архивом .ocmod.zip. Подробно: страница «Как установить модуль».&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Модули меняют файлы ядра?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Нет. Модули работают через OCMOD, события и собственные файлы; изменения обратимы — их можно отключить и удалить.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Что будет после обновления модуля?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Загрузите новый архив поверх старого, обновите модификаторы и один раз сохраните настройки. Перед обновлением делайте резервную копию.&quot;}}, {&quot;@type&quot;: &quot;Question&quot;, &quot;name&quot;: &quot;Куда обратиться за помощью?&quot;, &quot;acceptedAnswer&quot;: {&quot;@type&quot;: &quot;Answer&quot;, &quot;text&quot;: &quot;Напишите на support@codecartpro.com или в Telegram-сообщество проекта. Условия лицензии, гарантии и возврата — на странице «Лицензия, гарантия и возврат».&quot;}}]}&lt;/script&gt;','FAQ: модули CodeCart PRO, лицензии, демо, установка','Ответы на частые вопросы: бесплатна ли система CodeCart PRO 3.0.6.0, как проверить модуль, какие версии OpenCart поддерживаются, как работает лицензия и обновления.','','Частые вопросы о модулях и системе CodeCart PRO');
